/**
 * Every sound in the game: one list that drives the engine, `docs/audio/sound-list.md` (generated by
 * tools/audio/sound-list.ts) and the sound board (`?scene=sounds`).
 *
 * Audio v3 (claude/audio/03-spec-sfx-rework-insect.md): every effect is a file. Each sound's takes are rendered
 * offline by tools/audio/sfx (one recipe per sound, from the physics of the real thing: docs/audio/sound-research.md)
 * or come from a recording in audio-src/recordings, and are packed into one file per sound
 * (`public/audio/<folder>/<name>.ogg` and `.m4a`, its takes one after another) listed in `public/audio/manifest.json`.
 * Only the music and the narration cue are still made in the game (`recipe`, instruments.ts).
 */

export type Bus = 'ambience' | 'creatures' | 'combat' | 'ui' | 'music' | 'narration';

export interface SoundDef {
  id: string;
  bus: Bus;
  /** section of the sound list */
  group: string;
  /** what it should sound like */
  desc: string;
  /** typical length */
  dur: string;
  /** variations (takes) in its file */
  takes: number;
  /** level in the mix (0–1) */
  gain: number;
  /** random pitch, ± fraction (0.08 = ±8 %) */
  pitch: number;
  /** random volume, ± fraction */
  vol: number;
  /** most voices of this sound at once */
  voices: number;
  /** a looping bed (ambience, the battle and scuffle textures) */
  loop?: boolean;
  /** long file: streamed, not decoded whole (music, long ambience) */
  stream?: boolean;
  /** made in the game (instruments.ts): the music stingers and the narration cue */
  recipe?: string;
  /** suggested search terms for libraries and Freesound */
  search: string[];
  /** how to record it yourself */
  foley: string;
  /** not used by the game yet (a species, creature or feature still to come) */
  reserved?: string;
  /** no high content: decoded at 1/2 or 1/4 of the sample rate (memory) */
  down?: 2 | 4;
}

const d = (
  id: string,
  bus: Bus,
  group: string,
  desc: string,
  o: Partial<SoundDef> & { search: string[]; foley: string; dur: string },
): SoundDef => ({ id, bus, group, desc, takes: 5, gain: 0.7, pitch: 0.07, vol: 0.15, voices: 4, ...o });

